"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState, type CSSProperties, type KeyboardEvent } from "react";

/*
 * Region DACH – a map illustration of Germany, Austria and Switzerland, in a single self-contained file.
 * The countries sit filled in the middle; the outlines of the neighbouring countries fade out towards
 * the edges. A soft pastel band travels along the outer border in a continuous loop.
 * A small menu in the top-left corner switches to the United States, China, India, Brazil or Japan;
 * the old map fades out while the new one fades in.
 * Drawn on a 540 × 440 viewBox from Natural Earth country shapes (public domain).
 */

export type Region = "dach" | "us" | "cn" | "in" | "br" | "jp";

export type RegionDachProps = {
  /** Shown region (controlled) */
  region?: Region;
  /** Region shown first when `region` is not set */
  defaultRegion?: Region;
  /** Called when the viewer picks a region in the menu */
  onRegionChange?: (region: Region) => void;
  /** Show the region menu in the top-left corner */
  showSwitcher?: boolean;
  className?: string;
  /** Accessible description of the map; a function receives the current region */
  label?: string | ((region: Region) => string);
};

const OPTIONS: { value: Region; name: string; label: string }[] = [
  { value: "dach", name: "DACH", label: "Map of the DACH region: Germany, Austria and Switzerland" },
  { value: "us", name: "United States", label: "Map of the United States" },
  { value: "cn", name: "China", label: "Map of China" },
  { value: "in", name: "India", label: "Map of India" },
  { value: "br", name: "Brazil", label: "Map of Brazil" },
  { value: "jp", name: "Japan", label: "Map of Japan" },
];

type Phase = "idle" | "enter" | "exit";

export function RegionDach({
  region,
  defaultRegion = "dach",
  onRegionChange,
  showSwitcher = true,
  className,
  label,
}: RegionDachProps) {
  const id = "ui-rd" + useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const root = useRef<HTMLDivElement>(null);
  const [own, setOwn] = useState<Region>(defaultRegion);
  const current = region ?? own;
  const option = OPTIONS.find((o) => o.value === current) ?? OPTIONS[0];

  const select = (next: Region) => {
    if (region === undefined) setOwn(next);
    if (next !== current) onRegionChange?.(next);
  };

  // The shown map plus any map that is still fading out
  const [layers, setLayers] = useState<{ key: number; region: Region; phase: Phase }[]>([
    { key: 0, region: current, phase: "idle" },
  ]);
  useEffect(() => {
    setLayers((all) => {
      const top = all[all.length - 1];
      if (top.region === current) return all;
      return [
        ...all.map((l) => ({ ...l, phase: "exit" as Phase })),
        { key: top.key + 1, region: current, phase: "enter" as Phase },
      ];
    });
  }, [current]);
  useEffect(() => {
    if (!layers.some((l) => l.phase === "exit")) return;
    const timer = setTimeout(() => setLayers((all) => all.filter((l) => l.phase !== "exit")), 480);
    return () => clearTimeout(timer);
  }, [layers]);

  // The menu scales with the illustration, so it still fits in small previews
  const [scale, setScale] = useState(1);
  useEffect(() => {
    const el = root.current;
    if (!el) return;
    const fit = () => setScale(Math.min(1, Math.max(0.62, el.clientWidth / 540)));
    fit();
    const observer = new ResizeObserver(fit);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return (
    <div
      ref={root}
      className={["ui-rd", className].filter(Boolean).join(" ")}
      style={{ "--ui-rd-s": scale } as CSSProperties}
    >
      {/* React 19 hoists this into <head> once, no matter how many instances render */}
      <style href="ui-region-dach" precedence="default">
        {css}
      </style>
      <div
        className="ui-rd-map"
        role="img"
        aria-label={typeof label === "function" ? label(current) : (label ?? option.label)}
      >
        <svg className="ui-rd-art" viewBox="0 0 540 440" aria-hidden="true">
          <defs>
            <filter id={`${id}-shadow`} x="-15%" y="-15%" width="130%" height="130%">
              <feDropShadow dx="0" dy="3" stdDeviation="3.5" floodColor="#1F2128" floodOpacity="0.07" />
            </filter>
            {/* Colors of the band that travels along the outer border */}
            <linearGradient id={`${id}-shine`} gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="540" y2="220">
              <stop offset="0%" stopColor="#FFA0AB" />
              <stop offset="33%" stopColor="#FFB89E" />
              <stop offset="66%" stopColor="#C8A8E5" />
              <stop offset="100%" stopColor="#A8B5FF" />
            </linearGradient>
            <filter id={`${id}-blur`} x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="4" />
            </filter>
          </defs>
          {layers.map((l) => (
            <MapLayer key={l.key} id={`${id}-${l.key}`} shared={id} region={l.region} phase={l.phase} />
          ))}
        </svg>
      </div>
      {showSwitcher && <Switcher value={current} onChange={select} />}
    </div>
  );
}

/* ---------- One map: neighbours, filled countries and the travelling band ---------- */

function MapLayer({ id, shared, region, phase }: { id: string; shared: string; region: Region; phase: Phase }) {
  const map = MAPS[region];
  const [cx, cy, r] = map.fade;
  return (
    <g className="ui-rd-layer" data-phase={phase}>
      <defs>
        {/* Hides the glow inside the countries, so it only spreads outwards from the border */}
        <mask id={`${id}-outside`} maskUnits="userSpaceOnUse" x="0" y="0" width="540" height="440">
          <rect x="0" y="0" width="540" height="440" fill="#FFFFFF" />
          {map.land.map((d, i) => (
            <path key={i} d={d} fill="#000000" />
          ))}
        </mask>
        {/* Neighbouring countries are visible near the map and fade out towards the edges */}
        <radialGradient id={`${id}-fade`} cx={cx} cy={cy} r={r} gradientUnits="userSpaceOnUse">
          <stop offset="0%" stopColor="#FFFFFF" stopOpacity="0.9" />
          <stop offset="65%" stopColor="#FFFFFF" stopOpacity="0.6" />
          <stop offset="90%" stopColor="#FFFFFF" stopOpacity="0.18" />
          <stop offset="100%" stopColor="#FFFFFF" stopOpacity="0" />
        </radialGradient>
        <mask id={`${id}-neighbors`} maskUnits="userSpaceOnUse" x="0" y="0" width="540" height="440">
          <rect x="0" y="0" width="540" height="440" fill={`url(#${id}-fade)`} />
        </mask>
      </defs>

      {/* Neighbouring countries: outlines only */}
      <g
        mask={`url(#${id}-neighbors)`}
        fill="none"
        stroke="#A6ABB3"
        strokeWidth="0.7"
        strokeLinejoin="round"
        strokeLinecap="round"
      >
        {map.neighbors.map((d, i) => (
          <path key={i} d={d} />
        ))}
      </g>

      {/* The region's countries */}
      <g filter={`url(#${shared}-shadow)`} fill="#F8F8F8" stroke="#D6D9DE" strokeWidth="0.9" strokeLinejoin="round">
        {map.land.map((d, i) => (
          <path key={i} d={d} />
        ))}
      </g>

      {/* Band on the outer border: a blurred glow underneath, three sharp layers with shorter dashes on top */}
      <g fill="none" stroke={`url(#${shared}-shine)`} strokeLinecap="round" strokeLinejoin="round">
        <path
          className="ui-rd-band"
          d={map.perimeter}
          pathLength={1000}
          strokeWidth="6"
          strokeDasharray="180 820"
          filter={`url(#${shared}-blur)`}
          mask={`url(#${id}-outside)`}
          opacity="0.45"
        />
        <path className="ui-rd-band" d={map.perimeter} pathLength={1000} strokeWidth="1.4" strokeDasharray="200 800" opacity="0.32" />
        <path
          className="ui-rd-band ui-rd-band--1"
          d={map.perimeter}
          pathLength={1000}
          strokeWidth="1.4"
          strokeDasharray="140 860"
          strokeDashoffset="-30"
          opacity="0.55"
        />
        <path
          className="ui-rd-band ui-rd-band--2"
          d={map.perimeter}
          pathLength={1000}
          strokeWidth="1.4"
          strokeDasharray="80 920"
          strokeDashoffset="-60"
        />
      </g>
    </g>
  );
}

/* ---------- Region menu: a pill that morphs open into a listbox ---------- */

function Switcher({ value, onChange }: { value: Region; onChange: (region: Region) => void }) {
  const id = "ui-rd-menu" + useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const trigger = useRef<HTMLButtonElement>(null);
  const panel = useRef<HTMLDivElement>(null);
  const rows = useRef<(HTMLDivElement | null)[]>([]);
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const [from, setFrom] = useState({ w: 0, h: 0 });
  const [fill, setFill] = useState({ y: 0, h: 0, glide: false });
  // The fill only shows while the pointer is over a row (or the keyboard moves through the list)
  const [shown, setShown] = useState(false);
  const wasShown = useRef(false);
  const selected = Math.max(
    0,
    OPTIONS.findIndex((o) => o.value === value),
  );

  // The closed menu is a trigger-sized pill in its top-left corner; opening morphs it to the full panel
  useLayoutEffect(() => {
    const t = trigger.current;
    if (t) setFrom({ w: t.offsetWidth, h: t.offsetHeight });
  }, [value, open]);

  const show = () => {
    setActive(selected);
    setShown(false);
    setOpen(true);
  };
  const close = (refocus: boolean) => {
    setOpen(false);
    if (refocus) trigger.current?.focus();
  };
  const pick = (i: number) => {
    onChange(OPTIONS[i].value);
    close(true);
  };

  useEffect(() => {
    if (open) panel.current?.focus({ preventScroll: true });
  }, [open]);

  // One fill glides between rows; when it first appears it fades in on the spot
  useLayoutEffect(() => {
    const row = rows.current[active];
    if (row) setFill({ y: row.offsetTop, h: row.offsetHeight, glide: wasShown.current && shown });
    wasShown.current = shown;
  }, [active, open, shown]);

  // Click outside closes
  useEffect(() => {
    if (!open) return;
    const away = (event: PointerEvent) => {
      const target = event.target as Node;
      if (panel.current?.contains(target) || trigger.current?.contains(target)) return;
      close(false);
    };
    document.addEventListener("pointerdown", away);
    return () => document.removeEventListener("pointerdown", away);
  }, [open]);

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const last = OPTIONS.length - 1;
    const moves: Record<string, number> = {
      ArrowDown: Math.min(last, active + 1),
      ArrowUp: Math.max(0, active - 1),
      Home: 0,
      End: last,
    };
    if (event.key in moves) {
      event.preventDefault();
      setActive(moves[event.key]);
      setShown(true);
    } else if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      pick(active);
    } else if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      close(true);
    } else if (event.key === "Tab") {
      close(false);
    }
  };

  return (
    <div className="ui-rd-switch">
      <button
        ref={trigger}
        type="button"
        className="ui-rd-trigger"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={`${id}-list`}
        aria-label={`Region: ${OPTIONS[selected].name}`}
        onClick={() => (open ? close(false) : show())}
        onKeyDown={(event) => {
          if (event.key === "ArrowDown" || event.key === "ArrowUp") {
            event.preventDefault();
            show();
          }
        }}
      >
        <span>{OPTIONS[selected].name}</span>
        <ChevronIcon />
      </button>
      <div
        className="ui-rd-menu"
        data-open={open}
        style={{ "--from-w": `${from.w}px`, "--from-h": `${from.h}px` } as CSSProperties}
        inert={!open}
      >
        <div
          ref={panel}
          id={`${id}-list`}
          className="ui-rd-panel"
          role="listbox"
          tabIndex={-1}
          aria-label="Select a region"
          aria-activedescendant={`${id}-${active}`}
          onKeyDown={onKeyDown}
          onPointerLeave={() => setShown(false)}
        >
          <span
            className="ui-rd-fill"
            aria-hidden="true"
            data-glide={fill.glide}
            style={{ transform: `translateY(${fill.y}px)`, height: fill.h, opacity: shown ? 1 : 0 }}
          />
          {OPTIONS.map((o, i) => (
            <div
              key={o.value}
              ref={(el) => {
                rows.current[i] = el;
              }}
              id={`${id}-${i}`}
              role="option"
              aria-selected={i === selected}
              className="ui-rd-option"
              onPointerEnter={() => {
                setActive(i);
                setShown(true);
              }}
              onClick={() => pick(i)}
            >
              <span className="ui-rd-option-name">{o.name}</span>
              <span className="ui-rd-check" aria-hidden="true">
                <TickIcon />
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

const ChevronIcon = () => (
  <svg className="ui-rd-chevron" viewBox="0 0 24 24" fill="none" aria-hidden="true">
    <path
      d="M18 9.00005C18 9.00005 13.5811 15 12 15C10.4188 15 6 9 6 9"
      stroke="#737373"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
);

const TickIcon = () => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth={1.75}
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
  >
    <path d="M5 14L8.5 17.5L19 6.5" />
  </svg>
);

/* ---------- Map data (Natural Earth, public domain), projected onto the 540 × 440 viewBox ---------- */

/** First subpath of a path: the main landmass, where the band travels */
const firstShape = (d: string) => d.slice(0, d.indexOf("z") + 1);

type MapData = {
  /** Filled countries */
  land: string[];
  /** Neighbouring countries, drawn as fading outlines */
  neighbors: string[];
  /** Outer border, where the band travels */
  perimeter: string;
  /** Centre and radius of the neighbours' fade */
  fade: [number, number, number];
};

